\copy (SELECT s.run_id, s.epoch, s.values->>'logic_share_echo' AS echo, s.values->>'logic_share_not' AS "not", s.values->>'logic_share_nand' AS nand, s.values->>'logic_share_and' AS "and", s.values->>'logic_share_orn' AS orn, s.values->>'logic_share_or' AS "or", s.values->>'logic_share_andn' AS andn, s.values->>'logic_share_nor' AS nor, s.values->>'logic_share_xor' AS xor, s.values->>'logic_share_equ' AS equ, s.values->>'logic_capability_deep' AS deep FROM samples s JOIN runs r ON r.id = s.run_id WHERE s.run_id IN (4845,4862,4863,4871,4890,4952,4961,4979,4980) AND s.epoch > r.parent_epoch ORDER BY s.run_id, s.epoch) TO STDOUT WITH CSV HEADER
